/**
 * Pass this object into the MfeWrapper which will allow you to
 * call updateConfig() to update the config inside the mfeWrapper.
 */
export class DynamicConfigController {
    constructor(initialConfig) {
        this.defaultConfig = initialConfig;
    }
    getDefaultConfig() {
        return this.defaultConfig;
    }
    /**
     * This is the main update function.
     * @param config The new config object to propagate down to your MFE
     */
    updateConfig(config) {
        if (typeof this.updaterFunction === 'function') {
            this.updaterFunction(config);
        }
    }
    setUpdaterFunction(updaterFn) {
        this.updaterFunction = updaterFn;
    }
    clearUpdaterFunction() {
        this.updaterFunction = undefined;
    }
}
